  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The required area each month (1500, 1000, 2000, 1200) — is the total rented area in each month required to be at least the required area (excess allowed), or must it equal the required area exactly?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether the rented area must be at least or exactly equal to the required area."
}

